const items = $input.all();

return items.map(item => {
  const body = item.json.body || item.json;

  // Contrato en camelCase (con fallback de seguridad)
  const destinatario = body.correo || body.email;
  const nombre = body.nombre || 'Usuario';
  const codigo = body.codigoVerificacion || body.codigo_verificacion;
  const expira = body.expiraEnMinutos || body.expira_en_minutos || 15;
  const usuarioId = body.usuarioId || body.usuario_id;

  const htmlTemplate = `
  <!DOCTYPE html>
  <html>
  <head>
    <meta charset="utf-8">
    <style>
      body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; background-color: #f4f4f7; margin: 0; padding: 20px; }
      .card { max-width: 480px; margin: 0 auto; background: #ffffff; border-radius: 8px; padding: 32px; box-shadow: 0 2px 8px rgba(0,0,0,0.05); }
      .header { text-align: center; margin-bottom: 24px; }
      .code-box { background: #0f172a; color: #38bdf8; font-size: 32px; font-weight: bold; letter-spacing: 6px; text-align: center; padding: 18px; border-radius: 6px; margin: 24px 0; }
      .footer { font-size: 12px; color: #64748b; text-align: center; margin-top: 24px; line-height: 1.5; }
    </style>
  </head>
  <body>
    <div class="card">
      <div class="header">
        <h2 style="color: #0f172a; margin: 0;">Verifica tu cuenta</h2>
      </div>
      <p style="color: #334155; font-size: 15px;">Hola <strong>${nombre}</strong>,</p>
      <p style="color: #334155; font-size: 15px;">Ingresa el siguiente código en la plataforma para completar tu registro institucional. Este código vence en <strong>${expira} minutos</strong>:</p>

      <div class="code-box">${codigo}</div>

      <p style="color: #64748b; font-size: 13px;">Si no solicitaste este registro, puedes ignorar este mensaje.</p>
      <div class="footer">
        Complejo Deportivo &copy; 2026. Todos los derechos reservados.
      </div>
    </div>
  </body>
  </html>
  `;

  return {
    json: {
      destinatario: destinatario,
      asunto: `${codigo} es tu código de verificación`,
      html: htmlTemplate,
      usuarioId: usuarioId
    }
  };
});
